}

Method.Source:
     /// <summary>
 ///     AVA <c>getDocuBrandDetailsTmp</c> method.
 /// </summary>
 /// <param name="_dataProvider">
 ///     <c>SrsReportDataProviderBase</c> as type
 /// </param>
 /// <returns>
 ///     <c>SysDocuBrandDetailsTmp</c> as return value
 /// </returns>
public static SysDocuBrandDetailsTmp getDocuBrandDetailsTmp(SrsReportDataProviderBase _dataProvider)
 {
     SysDocuBrandDetailsTmp tableTmp = next getDocuBRandDetailsTmp(_dataProvider);

     if (_dataProvider)
     {
         SysDocuBrandDetails table       = SysDocuBrandDetails::getBrandDocument(_dataProvider.parmDocuBrandContract());
         tableTmp.AVASender              = table.AVASender;
         tableTmp.AVAImage1International = table.AVAImage1International;
         tableTmp.AVAImage2International = table.AVAImage2International;
         tableTmp.AVAImage3International = table.AVAImage3International;
     }

     return tableTmp;
 }

