public static SysDocuBrandDetailsRegular getDocuBrandDetailsRegular(SrsReportDataProviderBase _dataProvider)
{
    SysDocuBrandDetailsRegular tableTmp = next getDocuBrandDetailsRegular(_dataProvider);

    if (_dataProvider)
    {
        SysDocuBrandDetails table  = SysDocuBrandDetails::getBrandDocument(_dataProvider.parmDocuBrandContract());
        tableTmp.AVASender         = table.AVASender;
        tableTmp.AVAImage1International = table.AVAImage1International;
        tableTmp.AVAImage2International = table.AVAImage2International;
        tableTmp.AVAImage3International = table.AVAImage3International;
    }

    return tableTmp;
}

/// <summary>
///     AVA <c>getBrandDocument</c> method.
/// </summary>
/// <param name="docuBrandContract">
///     <c>SysDocuBrandContract</c> as type
/// </param>
/// <returns>
///     <c>SysDocuBrandDetails</c> as return value
/// </returns>
public static SysDocuBrandDetails getBrandDocument(SysDocuBrandContract docuBrandContract)
{
    SysDocuBrandDetails         ret = next getBrandDocument(docuBrandContract);
    SysDocuBrandDetails         docuBrandDetails = SysDocuBrandDetails::getDefaultDocuBrandDetails(docuBrandContract);

    if (docuBrandDetails && docuBrandDetails.RecId != 0)
    {
        ret.AVASender                   = docuBrandDetails.AVASender;
        ret.AVAImage1NameInternational  = docuBrandDetails.AVAImage1NameInternational;
        ret.AVAImage1International      = docuBrandDetails.AVAImage1International;
        ret.AVAImage2NameInternational  = docuBrandDetails.AVAImage2NameInternational;
        ret.AVAImage2International      = docuBrandDetails.AVAImage2International;
        ret.AVAImage3NameInternational  = docuBrandDetails.AVAImage3NameInternational;
        ret.AVAImage3International      = docuBrandDetails.AVAImage3International;
    }
    else
    {
        // set the document branding defaults
        ret.AVASender                   = '';
        ret.AVAImage1NameInternational  = '';
        ret.AVAImage2NameInternational  = '';
        ret.AVAImage3NameInternational  = '';
    }

    if (ret.AVAImage1NameInternational)
    {
        ret.AVAImage1International  = SysDocuBrandImages::getImage(ret.AVAImage1NameInternational);
    }

    if (ret.AVAImage2NameInternational)
    {
        ret.AVAImage2International  = SysDocuBrandImages::getImage(ret.AVAImage2NameInternational);
    }

    if (ret.AVAImage3NameInternational)
    {
        ret.AVAImage3International  = SysDocuBrandImages::getImage(ret.AVAImage3NameInternational);
    }

    return ret;
}

/// <summary>
/// Returns SysDocuBrandDetails for empty or specified ReportName
/// used primarily for Electronic Reporting
/// </summary>
/// <param name = "_reportName">str</param>
/// <param name = "_companyId">CompanyId, defaulted to current company</param>
/// <returns>SysDocuBrandDetails</returns>
public static SysDocuBrandDetails avaGetDocuBrandDetails(str _reportName = '', CompanyId _companyId = curExt())
{
    SysDocuBrandDetails avaSysDocuBrandDetails;

    changecompany(_companyId)
    {
        select firstonly avaSysDocuBrandDetails
            where avaSysDocuBrandDetails.DataAreaId == _companyId
            && avaSysDocuBrandDetails.ReportName == _reportName;

        if(!avaSysDocuBrandDetails)
        {
            select firstonly avaSysDocuBrandDetails
                where avaSysDocuBrandDetails.DataAreaId == _companyId
                && avaSysDocuBrandDetails.ReportName == '';
        }
    }

    return avaSysDocuBrandDetails;
}

/// <summary>
///     AVA <c>avaPrimaryImage1</c> method.
///     AVA - Schneider 05.08.2024
/// </summary>
/// <param name="_languageId">
///     <c>LanguageId</c> as type
/// </param>
/// <returns>
///     <c>Bitmap</c> as return value
/// </returns>
public Bitmap avaPrimaryImage1(LanguageId _languageId = '')
{
    Bitmap retVal;

    LanguageId locLanguageIdCompany;
    LanguageId locLanguageId;

    locLanguageIdCompany    = CompanyInfo::find().LanguageId;

    locLanguageId           = _languageId;

    if(_languageId == '')
    {
        locLanguageId = locLanguageIdCompany;
    }

    if(locLanguageIdCompany == locLanguageId)
    {
        retVal = this.Image1;
    }
    else
    {
        if(this.AVAImage1International == conNull())
        {
            retVal = this.Image1;
        }
        else
        {
            retVal = this.AVAImage1International;
        }
    }
    return retVal;
}

